function ttWeekCompactRows(table,compact,col,today){
 const rows=[...table.tBodies[0].rows].filter(r=>!r.classList.contains('lunch-row'));
 const items=rows.map((r,i)=>({r,n:Number(r.cells[0]?.textContent.match(/\d+/)?.[0]),value:String(lastWeek?.rows[i]?.cells?.[col-1]||'').trim()}));
 let shown=items;
 if(compact){
  const lessons=items.filter(x=>x.value&&Number.isInteger(x.n)&&periods[x.n-1]);
  const source=lessons.length?lessons:items;
  let at=0;
  if(today&&lessons.length){const now=seoulClock().minute;at=source.findIndex(x=>now<toPeriodMinutes(periods[x.n-1][1]));if(at<0)at=source.length-1;}
  const start=Math.max(0,Math.min(at-1,source.length-3));shown=source.slice(start,start+3);
 }
 const visible=new Set(shown.map(x=>x.r));rows.forEach(r=>{r.hidden=compact&&!visible.has(r)});
 table.querySelectorAll('.lunch-row').forEach(r=>{r.hidden=compact});
 table.tHead.hidden=compact;
}
let ttWeekFitFrame=0,ttWeekFitMemo=null;
function ttWeekFitSoon(){if(!ttWeekFitFrame)ttWeekFitFrame=requestAnimationFrame(()=>{ttWeekFitFrame=0;ttWeekFit()})}
function ttWeekFit(){
 const box=$('#week'),table=box.querySelector('.schedule');if(!table||!box.clientWidth||!box.clientHeight)return;
 const rows=[...table.querySelectorAll('tr')].filter(r=>!r.hidden&&!r.closest('thead[hidden]'));
 const cells=rows.flatMap(r=>[...r.cells].filter(c=>!c.hidden));
 const key=JSON.stringify([box.clientWidth,box.clientHeight,box.className,getComputedStyle(box).fontFamily,rows.map(r=>[r.textContent,[...r.cells].map(c=>c.hidden)])]);
 if(ttWeekFitMemo?.table===table&&ttWeekFitMemo.key===key)return;
 table.querySelectorAll('td,th,.tt-subject').forEach(el=>el.style.removeProperty('font-size'));
 const set=n=>box.style.setProperty('--tt-week-font',n+'px');
 const fits=()=>{const b=box.getBoundingClientRect(),t=table.getBoundingClientRect();return t.bottom<=b.bottom+.1&&t.right<=b.right+.1&&box.scrollWidth<=box.clientWidth&&box.scrollHeight<=box.clientHeight&&cells.every(c=>c.scrollWidth<=c.clientWidth&&[...c.querySelectorAll('.tt-subject,.period-time,.period-start,.period-end,.lunch-pill,.now-badge')].every(el=>!el.getClientRects().length||el.scrollWidth<=el.clientWidth));};
 function largest(hide){box.classList.toggle('tt-hide-times',hide);let lo=.5,hi=56;set(lo);if(!fits())return lo;set(hi);if(fits())return hi;while(hi-lo>.25){const mid=(hi+lo)/2;set(mid);if(fits())lo=mid;else hi=mid}lo=Math.max(.5,lo-Math.max(.5,lo*.06));set(lo);return lo;}
 const withTime=largest(false);
 // Preserve useful time text when it fits at a readable size; otherwise prioritize subjects.
 const compact=box.classList.contains('tt-week-compact');
 if(compact&&layout.items.week.h<=6){largest(true)}else if(withTime<(compact?20:18)){const without=largest(true);if(without<withTime+1){box.classList.remove('tt-hide-times');set(withTime)}}
 ttWeekFitMemo={table,key:JSON.stringify([box.clientWidth,box.clientHeight,box.className,getComputedStyle(box).fontFamily,rows.map(r=>[r.textContent,[...r.cells].map(c=>c.hidden)])])};
}
let ttWeekFitSettle=0;
new ResizeObserver(()=>{ttWeekFitSoon();clearTimeout(ttWeekFitSettle);ttWeekFitSettle=setTimeout(()=>{ttWeekFitMemo=null;ttWeekFitSoon()},160)}).observe($('#week'));
document.fonts?.ready?.then(()=>{ttWeekFitMemo=null;ttWeekFitSoon()});
document.fonts?.addEventListener('loadingdone',()=>{ttWeekFitMemo=null;ttWeekFitSoon()});
